const body = $input.first().json.body || $input.first().json;
const query = $input.first().json.query || {};
const action = body.action || query.action || 'list';
const id = body.id || query.id;

let sql;
switch(action) {
  case 'create':
    sql = `INSERT INTO campaigns (name, industry, city, country, daily_limit) VALUES ('${body.name}', '${body.industry}', '${body.city}', '${body.country || 'Canada'}', ${body.dailyLimit || 1}) RETURNING *;`;
    break;
  case 'update':
    const sets = [];
    if (body.status) sets.push(`status = '${body.status}'`);
    if (body.dailyLimit) sets.push(`daily_limit = ${body.dailyLimit}`);
    sql = `UPDATE campaigns SET ${sets.join(', ')}, updated_at = NOW() WHERE id = ${id} RETURNING *;`;
    break;
  case 'get':
    sql = `SELECT c.*, (SELECT count(*) FROM prospects WHERE campaign_id = c.id) as total_prospects, (SELECT count(*) FROM prospects WHERE campaign_id = c.id AND status = 'emailed') as emails_sent, (SELECT count(*) FROM prospects WHERE campaign_id = c.id AND status IN ('opened','clicked','signed_up','integrated')) as emails_opened, (SELECT count(*) FROM prospects WHERE campaign_id = c.id AND status IN ('clicked','signed_up','integrated')) as emails_clicked, (SELECT count(*) FROM prospects WHERE campaign_id = c.id AND status IN ('signed_up','integrated')) as signups, (SELECT count(*) FROM prospects WHERE campaign_id = c.id AND status = 'integrated') as integrations FROM campaigns c WHERE c.id = ${id};`;
    break;
  case 'prospects':
    const page = parseInt(query.page) || 1;
    const limit = parseInt(query.limit) || 50;
    const offset = (page - 1) * limit;
    const statusFilter = query.status ? `AND status = '${query.status}'` : '';
    sql = `SELECT * FROM prospects WHERE campaign_id = ${id} ${statusFilter} ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset};`;
    break;
  default:
    sql = `SELECT c.*, (SELECT count(*) FROM prospects WHERE campaign_id = c.id) as total_prospects FROM campaigns c ORDER BY c.created_at DESC;`;
}

return [{ json: { sql, action } }];
